-- disc_51 (owner ruling): ONE generator for a lease's role bundle, at SEND.
-- The LESSOR's horse-care documents (emergency vet, care release) become part of
-- the contract role bundle generated by ensure_contract_role_documents at send,
-- instead of being generated by ensure_horse_documents at execution.
--   1. Activate the LESSOR role-document rows for HORSE_EMERGENCY_VET and
--      RELEASE_HORSE_CARE (they already exist, inactive).
--   2. contract_role_document_requirements: for a LEASE, these two are
--      'unassigned' (the bundle owns them → generated at send). For a sale/BOS
--      they stay 'ensure_horse_documents@execution' (unchanged). Also make the
--      staff exemption on the party check explicit: staff callers always pass;
--      the party check applies only to non-staff.
--   3. apply_contract_execution_effects: the LEASE branch no longer calls
--      ensure_horse_documents — execution generates nothing for a lease. The sale
--      branch is unchanged (the buyer's horse docs still generate at execution).
-- ensure_horse_documents is NOT removed: it is still used by the member horse-care
-- flow and by the sale-execution branch.

BEGIN;

-- ── 1. activate the two LESSOR role-document rows ───────────────────────────
UPDATE contract_role_documents
   SET active = true
 WHERE org_id = 'e656f20b-ef43-4725-9029-19e7f0190d9c'
   AND doc_role = 'LESSOR'
   AND template_key IN ('HORSE_EMERGENCY_VET', 'RELEASE_HORSE_CARE')
   AND NOT active;

-- ── 2. requirements: lease-aware owned_by + explicit staff exemption ────────
DO $mig$
DECLARE
  v_src text := pg_get_functiondef('public.contract_role_document_requirements(uuid)'::regprocedure);
  -- (a) staff exemption explicit: the combined check becomes two clauses so the
  --     intent ("staff always pass; party check is for non-staff") is in the code.
  v_chk_old text := 'IF NOT (coalesce(has_staff_access(), false)
          OR EXISTS (SELECT 1 FROM document_parties dp
                      WHERE dp.document_id = p_document_id
                        AND dp.contact_id = current_contact_id())) THEN
    RAISE EXCEPTION ''not a party to this contract'';
  END IF;';
  v_chk_new text := 'IF NOT coalesce(has_staff_access(), false) THEN
    -- non-staff caller: must be a party to this contract to read its requirements
    IF NOT EXISTS (SELECT 1 FROM document_parties dp
                    WHERE dp.document_id = p_document_id
                      AND dp.contact_id = current_contact_id()) THEN
      RAISE EXCEPTION ''not a party to this contract'';
    END IF;
  END IF;';
  -- (b) owned_by: for a lease, the horse-care pair is owned by the bundle.
  v_own_old text := 'CASE
               WHEN crd.template_key IN (''HORSE_EMERGENCY_VET'',''RELEASE_HORSE_CARE'')
                 THEN ''ensure_horse_documents@execution''
               ELSE ''unassigned'' END';
  v_own_new text := 'CASE
               WHEN crd.template_key IN (''HORSE_EMERGENCY_VET'',''RELEASE_HORSE_CARE'')
                    AND NOT is_horse_lease_template(v_key)
                 THEN ''ensure_horse_documents@execution''
               ELSE ''unassigned'' END';
BEGIN
  IF position(v_chk_old in v_src) = 0 THEN RAISE EXCEPTION 'req party-check block not found'; END IF;
  IF position(v_own_old in v_src) = 0 THEN RAISE EXCEPTION 'req owned_by block not found'; END IF;
  v_src := replace(v_src, v_chk_old, v_chk_new);
  v_src := replace(v_src, v_own_old, v_own_new);
  EXECUTE v_src;
END $mig$;

-- ── 3. execution no longer generates horse docs for a LEASE ─────────────────
DO $mig$
DECLARE
  v_src text := pg_get_functiondef('public.apply_contract_execution_effects()'::regprocedure);
  v_old text := '    -- ownership does not move: the LESSOR is still the owner of record, so the
    -- generator addresses the horse documents to them
    PERFORM ensure_horse_documents(v_horse, NEW.contract_id, true);';
  v_new text := '    -- ownership does not move: the LESSOR is still the owner of record. The
    -- LESSOR''s horse documents are generated at SEND as part of the contract role
    -- bundle (disc_51), so execution generates nothing for a lease.';
BEGIN
  IF position(v_old in v_src) = 0 THEN RAISE EXCEPTION 'execution lease-branch call not found'; END IF;
  v_src := replace(v_src, v_old, v_new);
  EXECUTE v_src;
END $mig$;

COMMIT;
